    private void connect(NasClient.Credentials c,boolean save){connectProfile(loginProfile.routes(c),c,save,()->{});}
    void connectProfile(NasProfile profile,NasClient.Credentials c,boolean save,Runnable completed){
        if(profileInvalid&&s.client==null){
            AlertDialog confirm=new AlertDialog.Builder(this).setTitle(getString(R.string.profile_recovery_title)).setMessage(getString(R.string.profile_recovery_message)).setPositiveButton(R.string.profile_recovery_yes,(d,n)->{
                try{loginProfile=NasProfile.recover(s.store);profileInvalid=false;address.setText(loginProfile.address);local.setText(loginProfile.local);ddns.setText(loginProfile.ddns);quick.setText(loginProfile.quick);NasClient.Credentials restored=new NasClient.Credentials(loginProfile.address,loginProfile.local,loginProfile.ddns,loginProfile.quick,c.user,c.password,c.otp);connectProfile(loginProfile,restored,save,completed);}catch(Exception invalid){toast(SynoApp.safeError(invalid));}
            }).setNegativeButton(R.string.profile_recovery_no,null).create();ownDialog(confirm);confirm.show();return;
        }
        if(s.busy||s.downloadBusy||s.metadataBusy){toast(getString(R.string.msg_wait_for_the_current_operation_to_finish_1a9f47));return;}
        try{NasRoutes.plan(c,true);}catch(Exception invalid){toast(SynoApp.safeError(invalid));return;}
        s.busy=true;s.status=getString(R.string.msg_connecting_to_the_nas_45317b);s.changed();View focus=getCurrentFocus();if(focus!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(focus.getWindowToken(),0);
        String startedNetwork=s.networkKey();boolean allowLocal=s.allowLocalNetwork();long editSession=s.connectionDraft.generation;
        s.profileIo.execute(()->{
            NasClient candidate=new NasClient(c).fork("SynoStreamLogin_"+UUID.randomUUID().toString().replace("-",""));
            try{
                candidate.connect(allowLocal);
                String oldAddress=s.store.get("address","");if(profile.owner(c.user).equals(AccountIdentity.owner(oldAddress,c.user)))AccountIdentity.migrateKeys(s.store,oldAddress,c.user);
                String owner=profile.owner(c.user);s.store.saveProfile(profile,c,save);String savedEdits=s.store.get("edits:"+owner,"{}");
                s.main.post(()->{
                    boolean keep=s.client!=null&&s.identity.equals(owner);NasClient previous=s.client;
                    s.forgetConnection();MainActivity active=s.currentActivity();if(active!=null)active.networkPlaybackStopped();s.stopService(new Intent(s,StreamService.class));
                    if(keep){int token=previous.suspendConnection();if(!s.retirement.install(previous,token,candidate,s.profileIo)){s.busy=false;s.status=getString(R.string.network_retry_needed);s.recovery.requireReconnect();s.checkNetwork();s.changed();return;}s.client=previous;}
                    else{if(previous!=null)s.profileIo.execute(previous::logout);s.client=candidate;s.downloads=null;s.downloadsOpen=false;s.identity=owner;s.edits=new LocalEdits(savedEdits);s.libraries=LibraryConfig.migrate(s.libraries);s.store.libraries(s.libraries);s.cleanCaches();}
                    s.store.put("libraries_owner",owner);s.demo=false;s.status=candidate.route;s.epoch++;s.busy=false;s.connectionEstablished(startedNetwork);if(s.connectionDraft.current(editSession)){s.connectionDraft.close();if(active!=null)active.closeConnectionEditor();}if(!isDestroyed())completed.run();
                    if(keep){s.changed();return;}
                    if(s.selectedLibrary.isEmpty())s.selectedLibrary=s.store.get("selected_library","");
                    if(s.selected()==null)s.selectedLibrary=LibraryConfig.defaultLibrary(s.libraries,true).optString("id");JSONObject chosen=s.selected();
                    if(chosen!=null){s.page=chosen.optBoolean("movie",true)?"movies":"shows";s.loadCache(chosen,()->{if(s.cards.isEmpty()||s.store.get("scan_pending","").equals(s.identity+"|"+chosen.optString("id")))s.scan(chosen);s.main.post(()->{MainActivity current=s.currentActivity();if(current!=null)current.offerExternalTorrent();});});}else{s.changed();s.main.post(()->{MainActivity current=s.currentActivity();if(current!=null)current.offerExternalTorrent();});}
                });
            }catch(Exception e){candidate.logout();String error=SynoApp.safeError(e);s.main.post(()->{s.status=error;s.busy=false;s.changed();MainActivity current=s.currentActivity();if(current!=null)current.toast(error);});}
        });
    }
